    def fillet_groups(shp):
        tops = []
        bots = []
        for ed in shp.Edges():
            bb = ed.BoundingBox()
            zmin, zmax = bb.zmin, bb.zmax
            ymin, ymax = bb.ymin, bb.ymax
            if abs(zmin - ZTOP) < 1e-6 and abs(zmax - ZTOP) < 1e-6:
                tops.append(ed)
            elif abs(zmin - ZBOT) < 1e-6 and abs(zmax - ZBOT) < 1e-6:
                isfront = (ymax - ymin) < 1e-7 and abs(ymin - YFRONT) < 1e-4
                if not isfront:
                    bots.append(ed)
        return tops, bots

    def apply_fillet(shp, edges):
        mk = BRepFilletAPI_MakeFillet(shp.wrapped)
        n = 0
        for ed in edges:
            try:
                mk.Add(RF, ed.wrapped)
                n += 1
            except Exception:
                pass
        if n == 0:
            return shp
        mk.Build()
        if not mk.IsDone():
            return None
        try:
            return Shape.cast(mk.Shape())
        except Exception:
            return None

    tops, bots = fillet_groups(body)
    out = apply_fillet(body, tops + bots)
    if out is None:
        out = body

    box = Solid.makeBox(2.0 * H, RF, RF, Vector(-H, -1.0, ZFOOT))
    cyl = Solid.makeCylinder(
        RF, 2.0 * H + 0.02, Vector(-H - 0.01, -1.0 + RF, ZFOOT + RF), Vector(1, 0, 0)
    )
    out = out.cut(box.cut(cyl)).clean()
    solids = out.Solids()
    if len(solids) == 1:
        return solids[0]
    return out


