    SURF = {}; TYPE = {}; SIGN = {}; FLOOPS = {}; ALPHA = {}
    APEX = {}; CAX = {}
    FACES = []
    for entry in _FACES:
        fid, code, prm, sign, loops = entry
        if code == 0:
            n = np.array(prm[:3]); off = prm[3]
            srf = Geom_Plane(gp_Pnt(*(n * off)), gp_Dir(*n)); tp = 'plane'
        elif code == 1:
            a = np.array(prm[:3]); ax = np.array(prm[3:6]); al = prm[6]
            xd = unit(np.cross(ax, [1, 0, 0] if abs(ax[0]) < .9 else [0, 1., 0]))
            srf = Geom_ConicalSurface(gp_Ax3(gp_Ax2(gp_Pnt(*a), gp_Dir(*ax), gp_Dir(*xd))), float(al), 0.0)
            tp = 'cone'; ALPHA[fid] = float(al)
            APEX[fid] = a; CAX[fid] = ax / np.linalg.norm(ax)
        elif code == 2:
            pt = np.array(prm[:3]); ax = np.array(prm[3:6]); R = prm[6]
            xd = unit(np.cross(ax, [1, 0, 0] if abs(ax[0]) < .9 else [0, 1., 0]))
            srf = Geom_CylindricalSurface(gp_Ax3(gp_Ax2(gp_Pnt(*pt), gp_Dir(*ax), gp_Dir(*xd))), float(R))
            tp = 'cylinder'
        elif code == 3:
            c = np.array(prm[:3]); R = prm[3]
