import cadquery as cq
import numpy as np

A = np.array([[-0.609997, -0.528253],
              [ 0.610000, -0.528281],
              [ 0.000009,  0.528281]])
R = 0.3901004
B = np.array([[ 0.108403, -0.696312],
              [-0.108189, -0.695653],
              [ 0.502972, -0.010228],
              [ 0.395120,  0.176521],
              [-0.394886,  0.176317],
              [-0.502295, -0.010340]])
q = 0.138893
P = np.array([[ 0.001447, -0.255509],
              [ 0.042455, -0.199576],
              [-0.004033, -0.178518]])
pr = np.array([0.3147002, 0.4377892, 0.3953126])

H = 0.0972252339
hz = 0.0416675
f = H - hz
HR = 0.305565
HC = np.array([[-0.608903, -0.527640],
               [ 0.608922, -0.527640],
               [ 0.000009, -0.176084],
               [ 0.000009,  0.527027]])

names = ['C0', 'C1', 'C3', 'B0', 'B1', 'B2', 'B3', 'B4', 'B5', 'Pb', 'Pl', 'Pr']
cen = {'C0': A[0], 'C1': A[1], 'C3': A[2],
       'B0': B[0], 'B1': B[1], 'B2': B[2], 'B3': B[3], 'B4': B[4], 'B5': B[5],
       'Pb': P[0], 'Pl': P[1], 'Pr': P[2]}
rad = {'C0': R, 'C1': R, 'C3': R,
       'B0': q, 'B1': q, 'B2': q, 'B3': q, 'B4': q, 'B5': q,
       'Pb': pr[0], 'Pl': pr[1], 'Pr': pr[2]}
for n in ('B3', 'B4'):
    v = cen[n] - cen['C3']
    cen[n] = cen['C3'] + v * (R + q) / np.sqrt(v[0] * v[0] + v[1] * v[1])
junc = [('C1', 'B0'), ('B0', 'Pb'), ('Pb', 'B1'), ('B1', 'C0'), ('C0', 'B5'),
        ('B5', 'Pl'), ('Pl', 'B4'), ('B4', 'C3'), ('C3', 'B3'), ('B3', 'Pr'),
        ('Pr', 'B2'), ('B2', 'C1')]


def _unit(v, np):
    return v / np.sqrt(v[0] * v[0] + v[1] * v[1])


def _key(p):
    return (round(float(p[0]), 9), round(float(p[1]), 9))


T = {}
for (x, y) in junc:
    p = cen[x] + rad[x] * _unit(cen[y] - cen[x], np)
    T[(x, y)] = p
    T[(y, x)] = p

arcs = {}
for x in names:
    nb = []
    for (u, v) in junc:
        if u == x:
            nb.append(v)
        elif v == x:
            nb.append(u)
    c = cen[x]
    d = _unit(_unit(cen[nb[0]] - c, np) + _unit(cen[nb[1]] - c, np), np)
    if x == 'C0' or x == 'C1' or x == 'C3':
        d = -d
    arcs[x] = {'p1': T[(x, nb[0])], 'p2': T[(x, nb[1])], 'mid': c + rad[x] * d}

ends = {}
for x in names:
    ends.setdefault(_key(arcs[x]['p1']), []).append(x)
    ends.setdefault(_key(arcs[x]['p2']), []).append(x)
order = []
cur = 'C1'
p = arcs[cur]['p1']
while True:
    a = arcs[cur]
    if _key(a['p1']) == _key(p):
        a2 = a
    else:
        a2 = {'p1': a['p2'], 'p2': a['p1'], 'mid': a['mid']}
    order.append(a2)
    p = a2['p2']
    if _key(p) == _key(order[0]['p1']):
        break
    nxt = ''
    for z in ends[_key(p)]:
        if z != cur:
            nxt = z
    cur = nxt

wp = cq.Workplane("XY").moveTo(float(order[0]['p1'][0]), float(order[0]['p1'][1]))
for a in order:
    wp = wp.threePointArc((float(a['mid'][0]), float(a['mid'][1])),
                          (float(a['p2'][0]), float(a['p2'][1])))
body = wp.close().extrude(2 * H).translate((0, 0, -H)).val()

tops = []
bots = []
for fc in body.Faces():
    try:
        nz = fc.normalAt(fc.Center()).z
    except Exception:
        continue
    if nz > 0.99:
        tops.append(fc)
    elif nz < -0.99:
        bots.append(fc)
rim = []
for e in tops[0].outerWire().Edges():
    rim.append(e)
for e in bots[0].outerWire().Edges():
    rim.append(e)
solid = cq.Workplane("XY").add(body).newObject(rim).fillet(f).val()

wp = cq.Workplane("XY").add(solid)
for k in range(4):
    hole = (cq.Workplane("XY").workplane(offset=-H)
            .center(float(HC[k, 0]), float(HC[k, 1]))
            .circle(HR).extrude(2 * H))
    wp = wp.cut(hole)
result = wp.val()

import cadquery as cq


V = cq.Vector

PROFILE = [
    (-1.00, -0.70),
    (-0.95, -0.70),
    (-0.95, -0.82),
    (-0.90, -0.82),
    (-0.90, -0.76),
    (-0.76, -0.76),
    (-0.76, -0.90),
    (-0.82, -0.90),
    (-0.82, -0.95),
    (-0.70, -0.95),
    (-0.70, -1.00),
    (-1.00, -1.00),
]

arms = []
for axis in range(3):
    def _p(u, v, axis=axis, V=V):
        if axis == 0:
            return V(-1.0, u, v)
        if axis == 1:
            return V(u, -1.0, v)
        return V(u, v, -1.0)

    edges = []
    for i in range(len(PROFILE) - 1):
        edges.append(cq.Edge.makeLine(
            _p(*PROFILE[i]), _p(*PROFILE[i + 1])))
    edges.append(cq.Edge.makeLine(_p(*PROFILE[-1]), _p(*PROFILE[0])))
    face = cq.Face.makeFromWires(cq.Wire.assembleEdges(edges))
    d = [0.0, 0.0, 0.0]
    d[axis] = 2.0
    arms.append(cq.Solid.extrudeLinear(face, V(*d)))

body = arms[0].fuse(arms[1], arms[2])

class _Outer(cq.selectors.Selector):
    def filter(self, objectList):
        out = []
        for o in objectList:
            bb = o.BoundingBox()

            def eq(a, b):
                return abs(a - b) < 1e-6

            x1 = eq(bb.xmin, -1.0) and eq(bb.xmax, -1.0)
            y1 = eq(bb.ymin, -1.0) and eq(bb.ymax, -1.0)
            z1 = eq(bb.zmin, -1.0) and eq(bb.zmax, -1.0)
            if (x1 and y1) or (x1 and z1) or (y1 and z1):
                out.append(o)
        return out

body = cq.Workplane("XY").add(body).edges(_Outer()).fillet(0.04).val()

relief = []
for axis in range(3):
    lo = [None, None, None]
    hi = [None, None, None]
    for k in range(3):
        if k == axis:
            lo[k], hi[k] = -0.95, -0.90
        else:
            lo[k], hi[k] = -0.82, -0.76
    relief.append(cq.Solid.makeBox(
        hi[0] - lo[0], hi[1] - lo[1], hi[2] - lo[2], V(*lo)))
for c in relief:
    body = body.cut(c)

C_OUT = -0.91
C_IN = -0.83
R_BIG = 0.055
R_SMALL = 0.035

cutters = []
for axis in range(3):
    for (cu, r, a0, a1) in [
        (C_OUT, R_BIG, -1.25, 0.6),
        (C_OUT, R_SMALL, 0.6, 1.25),
        (C_IN, R_SMALL, 0.5, 1.25),
    ]:
        if axis == 0:
            base, d = V(a0, cu, cu), V(1, 0, 0)
        elif axis == 1:
            base, d = V(cu, a0, cu), V(0, 1, 0)
        else:
            base, d = V(cu, cu, a0), V(0, 0, 1)
        cutters.append(cq.Solid.makeCylinder(r, a1 - a0, base, d))

for c in cutters:
    body = body.cut(c)

result = cq.Workplane("XY").add(body.clean())

