def _make_part():
    import math
    import cadquery as cq

    def poly_xz(pts, y0, y1):
        wp = cq.Workplane('XZ').moveTo(*pts[0])
        for p in pts[1:]:
            wp = wp.lineTo(*p)
        wp = wp.close()
        return wp.extrude(-(y1 - y0)).translate((0, y0, 0)).val()

    def poly_yz(pts, x0, x1):
        wp = cq.Workplane('YZ').moveTo(*pts[0])
        for p in pts[1:]:
            wp = wp.lineTo(*p)
        wp = wp.close()
        return wp.extrude(x1 - x0).translate((x0, 0, 0)).val()

    def arc_xz(ops, y0, y1):
        wp = cq.Workplane('XZ')
        for op in ops:
            if op[0] == 'm':
                wp = wp.moveTo(*op[1])
            elif op[0] == 'l':
                wp = wp.lineTo(*op[1])
            else:
                wp = wp.threePointArc(op[1], op[2])
        wp = wp.close()
        return wp.extrude(-(y1 - y0)).translate((0, y0, 0)).val()

    def chamfer(axis, f, s, zb, side, e=0.01, d=0.02):
        a, b = f + s * d, f - s * e
        if side == 'lo':
            pts = [(a, zb), (b, zb), (b, zb - d), (f, zb - d)]
        elif side == 'up':
            pts = [(a, zb), (b, zb), (b, zb + d), (f, zb + d)]
        else:
            pts = [(f, zb - d), (b, zb - d), (b, zb + d), (f, zb + d), (a, zb)]
        if axis == 'x':
            return poly_xz(pts, -0.3, 0.3)
        return poly_yz(pts, -0.7, 0.7)

    def strip(z0):
        ops = [('m', (-0.4, z0)),
               ('a', (-0.1, z0 + 0.06), (0.2, z0)),
               ('l', (0.2, z0 + 0.1)),
               ('l', (-0.4, z0 + 0.1))]
        return arc_xz(ops, 0.12, 0.2)

    def block():
        s = 0.18 / math.sqrt(2.0)
        ops = [('m', (0.2, -1.0)), ('l', (0.6, -1.0)), ('l', (0.6, -0.98))]
        for z0 in (-1.0, -0.6, -0.2, 0.2, 0.6):
            zc = z0 + 0.02
            ops.append(('a', (0.42 + s, zc + s), (0.42, zc + 0.18)))
            ops.append(('l', (0.6, zc + 0.36)))
            ops.append(('l', (0.6, min(z0 + 0.42, 1.0))))
        ops.append(('l', (0.2, 1.0)))
        return arc_xz(ops, -0.2, 0.2)

    solids = [cq.Solid.makeBox(0.2, 0.4, 2.0, cq.Vector(-0.6, -0.2, -1.0)),
              block()]
    for k in range(5):
        z0 = -1.0 + 0.4 * k
        solids.append(strip(z0))
        solids.append(cq.Solid.makeBox(0.6, 0.08, 0.04,
                                       cq.Vector(-0.4, -0.2, z0 + 0.18)))
    part = solids[0]
    for s in solids[1:]:
        part = part.fuse(s)

    cutters = []
    for k in range(5):
        zc = -0.8 + 0.4 * k
        cutters.append(cq.Solid.makeCylinder(0.1, 0.4,
                                             cq.Vector(-0.7, 0.0, zc),
                                             cq.Vector(1.0, 0.0, 0.0)))
    for zb in (-0.6, -0.2, 0.2, 0.6):
        cutters.append(chamfer('y', 0.2, -1, zb, 'both'))
        cutters.append(chamfer('y', -0.2, 1, zb, 'both'))
        cutters.append(chamfer('x', -0.6, 1, zb, 'both'))
        cutters.append(chamfer('x', 0.6, -1, zb, 'both'))
        cutters.append(chamfer('x', -0.4, -1, zb, 'lo'))
        cutters.append(poly_xz([(-0.42, zb), (-0.39, zb),
                                (-0.39, zb + 0.02), (-0.4, zb + 0.02)],
                               -0.3, 0.12))
        cutters.append(chamfer('x', 0.2, 1, zb, 'lo'))
        cutters.append(poly_xz([(0.22, zb), (0.19, zb),
                                (0.19, zb + 0.02), (0.2, zb + 0.02)],
                               -0.3, 0.12))
    cutters.append(chamfer('y', 0.2, -1, -1.0, 'up'))
    cutters.append(chamfer('y', -0.2, 1, -1.0, 'up'))
    cutters.append(chamfer('x', -0.6, 1, -1.0, 'up'))
    cutters.append(chamfer('x', 0.6, -1, -1.0, 'up'))
    cutters.append(poly_xz([(-0.42, -1.0), (-0.39, -1.0),
                            (-0.39, -0.98), (-0.4, -0.98)], -0.3, 0.12))
    cutters.append(poly_xz([(0.22, -1.0), (0.19, -1.0),
                            (0.19, -0.98), (0.2, -0.98)], -0.3, 0.12))
    cutters.append(chamfer('y', 0.2, -1, 1.0, 'lo'))
    cutters.append(chamfer('y', -0.2, 1, 1.0, 'lo'))
    cutters.append(chamfer('x', -0.6, 1, 1.0, 'lo'))
    cutters.append(chamfer('x', 0.6, -1, 1.0, 'lo'))
    cutters.append(chamfer('x', -0.4, -1, 1.0, 'lo'))
    cutters.append(chamfer('x', 0.2, 1, 1.0, 'lo'))

    tool = cutters[0]
    for c in cutters[1:]:
        tool = tool.fuse(c)
    return part.cut(tool)


